        let fromInputs = Inputs.buffers(Int16.self, count: H.laneCount, seed: 0x2D10_6EB5_57FE_4C4B)
        let countInputs = Inputs.bufferCounts(lanes: H.laneCount)
        for (from, count) in everyPair(fromInputs, countInputs) {
            let (portResult, referenceResult) = unsafe withGuardedLanes(Array(from.prefix(count))) {
                source in
                (
                    unsafe H.loadFirstWidening(from: source, count: count),
                    unsafe port(HighwayReference.loadFirstWideningI16ToI32(source, count))
                )
            }.result
            mismatches.check(
                portResult,
                referenceResult,
                "from: \(describe(from)), count: \(count)"
            )
        }
        mismatches.record()
    }

    @Test func repeatingBlock() {
        let mismatches = Mismatches("repeatingBlock")
        let vectorInputs = Inputs.vectors(H.Vector.self, seed: 0x1FB3_7DDB_6B5F_7567)
        for vector in vectorInputs {
            mismatches.check(
                H.repeatingBlock(vector[0], vector[1], vector[2], vector[3]),
                port(
                    HighwayReference.repeatingBlockI32(vector[0], vector[1], vector[2], vector[3])
                ),
                "lanes: \(describe(vector))"
            )
        }
        mismatches.record()
    }
}
